('e4000001-0000-0000-0000-000000000010', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000002', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'OUTBOUND', 'TEXT', 'DELIVERED', 'ai', '{"text":"Report sent to rajesh.kumar@yahoo.com. Next checkup due around July 20th."}', 'Report sent', true, 0.94, NOW()-INTERVAL '1 day'+INTERVAL '5 min'+INTERVAL '20 seconds', NOW()-INTERVAL '1 day'+INTERVAL '5 min'+INTERVAL '20 seconds', NOW()),
('e4000001-0000-0000-0000-000000000030', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000010', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'INBOUND', 'TEXT', 'DELIVERED', 'client', '{"text":"I was prescribed metformin by another doctor. But I already take glimepiride. Is it safe to take both?"}', 'Metformin with glimepiride safe?', false, NULL, NOW()-INTERVAL '4 hours', NOW()-INTERVAL '4 hours', NOW()),
('e4000001-0000-0000-0000-000000000031', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000010', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'OUTBOUND', 'TEXT', 'DELIVERED', 'ai', '{"text":"Lakshmi ji, medication interactions are important. Connecting you with Dr. Kapoor directly. Please do NOT start the new medication until you hear back."}', 'Escalating to medical team', true, 0.65, NOW()-INTERVAL '4 hours'+INTERVAL '20 seconds', NOW()-INTERVAL '4 hours'+INTERVAL '20 seconds', NOW()),
('e4000001-0000-0000-0000-000000000032', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000010', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'OUTBOUND', 'TEXT', 'DELIVERED', 'human', '{"text":"Hello Lakshmi ji, this is Dr. Kapoor. Adding metformin needs careful dosage review with your current prescriptions."}', 'Dr. Kapoor responding', false, NULL, NOW()-INTERVAL '3 hours'-INTERVAL '30 min', NOW()-INTERVAL '3 hours'-INTERVAL '30 min', NOW()),
('e4000001-0000-0000-0000-000000000033', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000010', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'INBOUND', 'TEXT', 'DELIVERED', 'client', '{"text":"Dr. Sinha at City Hospital, metformin 500mg twice daily."}', 'Dr. Sinha prescribed metformin 500mg', false, NULL, NOW()-INTERVAL '3 hours', NOW()-INTERVAL '3 hours', NOW()),
('e4000001-0000-0000-0000-000000000025', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000008', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'INBOUND', 'TEXT', 'DELIVERED', 'client', '{"text":"Good morning. I need to refill my Warfarin prescription. 3 days supply left."}', 'Warfarin refill needed', false, NULL, NOW()-INTERVAL '6 hours', NOW()-INTERVAL '6 hours', NOW()),
('e4000001-0000-0000-0000-000000000026', '9d35a0c8-52c0-4616-ba92-4aeb017c9ea0', 'd3000001-0000-0000-0000-000000000008', '7f51962b-4dd3-4d19-83a0-bcffc9d03594', 'OUTBOUND', 'TEXT', 'DELIVERED', 'ai', '{"text":"Good morning Vikram ji! I see your Warfarin 5mg from Dr. Mehra. Shall I send renewal request and book your INR blood test?"}', 'Can process Warfarin renewal', true, 0.89, NOW()-INTERVAL '6 hours'+INTERVAL '30 seconds', NOW()-INTERVAL '6 hours'+INTERVAL '30 seconds', NOW()),
